DROP TABLE IF EXISTS `card_template_versions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `card_template_versions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `template_id` bigint(20) unsigned NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `name` varchar(120) NOT NULL,
  `design` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`design`)),
  `note` varchar(200) DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `card_template_versions_template_id_version_unique` (`template_id`,`version`),
  KEY `card_template_versions_user_id_foreign` (`user_id`),
  CONSTRAINT `card_template_versions_template_id_foreign` FOREIGN KEY (`template_id`) REFERENCES `card_templates` (`id`) ON DELETE CASCADE,
  CONSTRAINT `card_template_versions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

