CREATE TABLE `raffle_entries` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_id` bigint(20) unsigned NOT NULL,
  `number` varchar(20) NOT NULL,
  `name` varchar(150) DEFAULT NULL,
  `email` varchar(190) DEFAULT NULL,
  `country` varchar(100) DEFAULT NULL,
  `source` varchar(20) NOT NULL DEFAULT 'manual',
  `added_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `raffle_entries_event_id_number_unique` (`event_id`,`number`),
  KEY `raffle_entries_added_by_foreign` (`added_by`),
  CONSTRAINT `raffle_entries_added_by_foreign` FOREIGN KEY (`added_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `raffle_entries_event_id_foreign` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
