--
-- Table structure for table `registrations`
--

DROP TABLE IF EXISTS `registrations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `registrations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_id` bigint(20) unsigned DEFAULT NULL,
  `participant_id` bigint(20) unsigned DEFAULT NULL,
  `venue` varchar(255) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `trackingNo` varchar(255) DEFAULT NULL,
  `onbehalf` varchar(255) DEFAULT NULL,
  `country` varchar(255) DEFAULT NULL,
  `firstname` varchar(255) DEFAULT NULL,
  `lastname` varchar(255) DEFAULT NULL,
  `birthday` varchar(255) DEFAULT NULL,
  `gender` varchar(255) DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `profession` varchar(255) DEFAULT NULL,
  `specialty` varchar(255) DEFAULT NULL,
  `pharmacist` varchar(255) DEFAULT NULL,
  `designation` varchar(255) DEFAULT NULL,
  `institute` varchar(255) DEFAULT NULL,
  `institute_address` varchar(255) DEFAULT NULL,
  `institute_phone` varchar(255) DEFAULT NULL,
  `identification_type` varchar(255) DEFAULT NULL,
  `identification_no` varchar(255) DEFAULT NULL,
  `image` varchar(255) DEFAULT NULL,
  `qr_code` varchar(255) DEFAULT NULL,
  `qr_img` varchar(255) DEFAULT NULL,
  `qr_url` varchar(255) DEFAULT NULL,
  `verify_at` varchar(255) DEFAULT NULL,
  `verify_status` enum('Yes','No') NOT NULL DEFAULT 'No',
  `email_notification` enum('Yes','No') NOT NULL DEFAULT 'No',
  `qr_img_path` varchar(255) DEFAULT NULL,
  `gift` enum('Pending','Approved','Rejected') NOT NULL DEFAULT 'Pending',
  `status` enum('Pending','Approved','Rejected') NOT NULL DEFAULT 'Approved',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `registrations_event_email_unique` (`event_id`,`email`),
  KEY `registrations_email_index` (`email`),
  KEY `registrations_participant_id_foreign` (`participant_id`),
  CONSTRAINT `registrations_event_id_foreign` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`),
  CONSTRAINT `registrations_participant_id_foreign` FOREIGN KEY (`participant_id`) REFERENCES `participants` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=561 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

